/* ═══════════════════════════════════════════════════════════════════════
   LES PISTES
   ───────────────────────────────────────────────────────────────────────
   Una línia per pista. La clau és   'unitat/exercici'   i el valor, el text
   que veurà l'alumne quan premi el botó 💡.

     'apl-ud10/U4.24': 'Substitueix <i>x</i> = 2 i <i>y</i> = −1 a cada equació...',
     'apl-ud4/4.2.7':  'Busca els dos triangles semblants: tots dos tenen un angle recte...',

   Un exercici sense línia aquí simplement no mostra cap botó de pista: no
   cal escriure-hi res ni deixar-la buida.

   L'apòstrof s'ha d'escapar amb barra invertida:  d\'una  ,  fixa\'t
   (o fes servir l'apòstrof tipogràfic ’, que no cal escapar).

   Format: només <i>, <b> i <br>. L'estil de les pistes és a CLAUDE.md.

   Es pot editar des del mòbil: GitHub → hints.js → llapis → Commit changes.
   ═══════════════════════════════════════════════════════════════════════ */

const PISTES = {

  /* ── 4t ESO Aplicades · Unitat 1 · Nombres reals des de l’estimació ── */
  'apl-ud1/U1.4': 'L\'arrel quadrada d\'un nombre natural:<br>- és un nombre natural si fem l\'arrel quadrada d\'un <b>quadrat perfecte</b> (1, 4, 9, 16…): llavors l\'arrel és exacta.<br>- és un nombre <b>irracional</b> en tots els altres casos: un nombre decimal amb infinites xifres i que, a més a més, no repeteixen cap cicle.',
  'apl-ud1/U1.5': 'Mira com són les xifres decimals i decideix quin tipus de nombre és:<br>- Si s\'acaben, és un <b>decimal exacte</b>, i per tant racional.<br>- Si són infinites i es repeteixen sempre igual, és un <b>decimal periòdic</b>, i també és racional.<br>- Si són infinites i no es repeteixen, és un <b>nombre irracional</b>.',
  'apl-ud1/U1.6': 'Pots fer servir arrels quadrades de nombres que no siguin quadrats perfectes, o també el nombre π, entre d\'altres idees.',
  'apl-ud1/U1.40': 'L\'arrel quadrada d\'un nombre natural:<br>- és un nombre natural si fem l\'arrel d\'un <b>quadrat perfecte</b> (1, 4, 9…);<br>- és un nombre <b>irracional</b> en tots els altres casos.',
  'apl-ud1/U1.41': 'Abans de classificar cada nombre, fes totes les operacions que es puguin fer i simplifica.',
  'apl-ud1/U1.23': 'La diagonal divideix el rectangle en dos <b>triangles rectangles</b>: aplicant el teorema de Pitàgores podràs trobar quant mesura la diagonal, perquè en el fons és la hipotenusa d\'un triangle rectangle.',
  'apl-ud1/U1.46': 'Dibuixa l\'altura en el triangle equilàter i veuràs que el divideix en dos triangles rectangles:<br>- la hipotenusa és el costat del triangle<br>- un catet és la meitat del costat<br>- l\'altre catet és l\'altura que has dibuixat.<br>Aplicant el teorema de Pitàgores podràs trobar l\'altura.',
  'apl-ud1/U1.8': '- Per a les <b>arrels</b>, fes servir el teorema de Pitàgores. Per exemple, √10 és la hipotenusa d\'un triangle rectangle de catets 3 i 1.<br>- Per als <b>decimals</b>, mira primer entre quins dos enters són i després entre quines dècimes.<br>- Per a <b>2π</b>, n\'hi ha prou amb una aproximació.',
  'apl-ud1/U1.10': '<b>a)</b> Llegeix a la recta quin nombre correspon a cada lletra.<br><br><b>b)</b> Entre dos enters hi ha infinits nombres racionals: pensa en decimals exactes o en fraccions.<br><br><b>c)</b> Per escriure irracionals, pots fer servir arrels quadrades o sumar un nombre a π o a √2, mirant que el resultat quedi entre <i>C</i> i <i>D</i>.',
  'apl-ud1/U1.43': 'Fes servir el teorema de Pitàgores: busca un triangle rectangle de catets enters la hipotenusa del qual sigui l\'arrel que vols representar.<br>Per exemple, √5 és la hipotenusa d\'un triangle de catets 1 i 2, perquè 1² + 2² = 5.',
  'apl-ud1/U1.45': 'Calcula amb la calculadora el valor decimal de cada nombre, amb tres decimals, i ordena\'ls.',
  'apl-ud1/U1.20': '- Per <b>truncar</b>, talla el nombre a les centèsimes i no miris res més.<br>- Per <b>arrodonir</b>, mira la xifra de les mil·lèsimes: si és 5 o més, la xifra de les centèsimes augmenta 1.<br>Per exemple:<br>24,1587 truncat a les centèsimes és 24,15, però arrodonit a les centèsimes és 24,16.',
  'apl-ud1/U1.21': 'Per arrodonir a les unitats, mira la primera xifra decimal: si és {5, 6, 7, 8, 9}, llavors s\'arrodoneix a l\'alça.<br>Per exemple:<br><b>i)</b> 3,8 s\'arrodoneix a 4.<br><b>ii)</b> 3,2 s\'arrodoneix a 3.',
  'apl-ud1/U1.22': 'En primer lloc, escriu cada nombre amb <b>quatre decimals</b>. Per exemple, 11/9 ≈ 1,2222.<br>Posteriorment, trunca\'l a les centèsimes, i arrodoneix-lo a les centèsimes.',
  'apl-ud1/U1.83': 'Fes cada operació de les dues maneres:<br>- en primer lloc, opera-ho tot i, com a últim pas, arrodoneix el resultat;<br>- en segon lloc, arrodoneix cada nombre i després opera-ho tot.<br>Compara els dos resultats amb el resultat exacte: l\'<b>error</b> és la diferència entre el valor aproximat i el valor exacte.',
  'apl-ud1/U1.11': 'Recorda els conjunts numèrics, de més petit a més gran: <b>naturals</b>, <b>enters</b>, <b>racionals</b> i <b>reals</b>.<br>(El conjunt dels nombres <b>irracionals</b> està format per tots els nombres reals que no siguin racionals.)',
  'apl-ud1/U1.12': 'El <b>menor conjunt</b> és el conjunt més petit on hi pertany el nombre.<br>Per exemple, tot i que el −5 és un nombre real, també és un <b>nombre enter</b>.<br><b>Atenció</b>: en primer lloc, simplifica el que es pugui, com per exemple, √625, que és una arrel exacta.',
  'apl-ud1/U1.50': 'Pista: el nombre 418 és un nombre enter i racional, però també és nombre natural i per tant respondrem «natural» en aquest cas, perquè és el menor conjunt on hi pertany.',
  'apl-ud1/U1.52': 'En primer lloc, fes les operacions que es puguin fer i mira si l\'arrel és exacta. Per exemple, √(17 + 8) = √25 = 5.<br><b>Atenció</b>: tingues en compte que un nombre pot pertànyer a més d\'un conjunt: un natural també és enter, racional i real.',
  'apl-ud1/U1.53': 'Passa cada nombre a forma decimal amb la calculadora i, posteriorment, ordena\'ls. Per exemple, 7/3 ≈ 2,333.',
  'apl-ud1/U1.60': 'En primer lloc, passa cada decimal periòdic a fracció. Per exemple, 2,777… = 25/9.<br>Posteriorment, opera amb les fraccions i comprova si finalment obtens una arrel exacta.',
  'apl-ud1/U1.FN': 'Les tres quartes parts i el terç són parts del total d\'assistents. Suma 3/4 + 1/3: quina part del total obtens?<br>Té sentit que sumi més que 1? És a dir, més que el 100 %?',
  'apl-ud1/U1.82': 'Calcula el valor decimal de cada aproximació i arrodoneix-lo a sis decimals (a les milionèsimes). Després, calcula:<br>- l\'<b>error absolut</b>: la diferència, en valor absolut, entre l\'aproximació i el valor de π;<br>- l\'<b>error relatiu</b>: l\'error absolut dividit pel valor de π.',

  /* ── 4t ESO Aplicades · Unitat 2 · Percentatges i matemàtica financera ── */
  'apl-ud2/U2.27': 'Divideix el nombre d\'estudiants de cada activitat pel total (que és 432), i multiplica-ho per 100.',
  'apl-ud2/U2.28': 'Per aplicar un augment del 5,8 %, pots fer servir directament el <b>factor multiplicador</b>: 1,058.<br>(Un altre exemple: si l\'augment és d\'un 30 %, llavors el factor multiplicador és 1,30.)',
  'apl-ud2/U2.29': 'Si la palla és el 60 % del pes, vol dir que el gra és el 40 % restant. Calcula:<br>- quantes tones hi ha de <b>gra</b> i de <b>palla</b>;<br>- quants diners en treu de cadascun, multiplicant les tones pel seu preu.',
  'apl-ud2/U2.30': 'Si la natalitat ha baixat un 12,5 %, vol dir que ha passat del 100 % al 87,5 %.<br>També sabem que els 98 nadons d\'aquest any corresponen al 87,5 %.<br>Tens una situació de proporció directa: aplica la proporció, planteja l\'equació i trobaràs la resposta.',
  'apl-ud2/U2.89': 'Per exemple, «tres de cada vint» és la fracció 3/20.<br>Per expressar-ho com un percentatge, planteja una situació de proporcionalitat:<br>3/20 = <i>x</i>/100.',
  'apl-ud2/U2.90': 'En alguns casos, es pot fer gairebé mentalment:<br>- el 50 % és trobar la meitat.<br>- el 10 % és la desena part.<br>- el 25 % és la quarta part.',
  'apl-ud2/U2.91': 'L\'aigua que conté és el 45 % de la capacitat màxima (que és 200 hm³).',
  'apl-ud2/U2.31': 'Fes el camí a l\'inrevés:<br>- en primer lloc, 112 és el 20 % de la quantitat augmentada: troba aquesta quantitat amb una proporció directa;<br>- posteriorment, la quantitat augmentada és la inicial multiplicada pel <b>factor multiplicador</b> 1,12.',
  'apl-ud2/U2.33': 'Els percentatges encadenats es fan multiplicant els <b>factors multiplicadors</b>: augmentar un 28 % és multiplicar per 1,28, i rebaixar un 12 %, per 0,88.<br>Per tant, si anomenem <i>x</i> el preu inicial, tenim una equació: <i>x</i> · 1,28 · 0,88 = 527,85.',
  'apl-ud2/U2.35': 'Si no saps com començar, prova-ho amb un preu concret, per exemple 100 €: augmenta\'l un 15 % i, al resultat que obtinguis, resta-li un 15 %.',
  'apl-ud2/U2.92': 'Si vols aplicar dues vegades un augment del 3 %, pots multiplicar dues vegades pel <b>factor multiplicador</b>: 1,03.<br><b>Atenció</b>: pujar dues vegades un 3 % no equival a pujar un 6 %, saps per quin motiu?',
  'apl-ud2/U2.96': '<b>a)</b> Si ha disminuït un 20 %, vol dir que ha passat del 100 % al 80 %. També sabem que els 1 500 estudiants d\'ara corresponen al 80 %: tens una situació de proporció directa.',
  'apl-ud2/U2.99': '<b>Atenció</b>: et demanen quants diners puja cada article, no el preu final: n\'hi ha prou de calcular el 24 % de cada preu. És a dir, que en aquest cas <b>el factor multiplicador</b> és 0,24, i no 1,24.',
  'apl-ud2/U2.32': 'En primer lloc, aplica el descompte al preu del cotxe i, posteriorment, l\'IVA al preu rebaixat. Ho pots fer de cop multiplicant pels dos <b>factors multiplicadors</b>: 0,80 i 1,21.',
  'apl-ud2/U2.97': 'En primer lloc aplica el descompte i, posteriorment, l\'IVA sobre el preu ja rebaixat: pots multiplicar els 240 € pels <b>factors multiplicadors</b>: 0,80 i 1,21.',
  'apl-ud2/U2.98': 'Guanyar un 20 % vol dir vendre a un preu un 20 % més alt que el de compra: pots fer servir el <b>factor multiplicador</b> 1,20.',
  'apl-ud2/U2.103': 'Fes el camí a l\'inrevés: primer s\'afegeix el guany al preu inicial i, després, l\'IVA sobre aquest preu.<br>Per tant, si anomenem <i>x</i> el preu inicial, tenim aquesta equació: <i>x</i> · 1,10 · 1,21 = 60.',
  'apl-ud2/U2.104': 'En primer lloc el descompte i, posteriorment, l\'IVA sobre el preu rebaixat. Pots fer-ho de cop amb els dos <b>factors multiplicadors</b>: 0,75 i 1,21.',
  'apl-ud2/U2.105': '<b>a)</b> L\'IVA és el 21 % del preu de venda. Cada intermediari paga IVA quan compra i en cobra quan ven: el que li toca pagar és la diferència.<br><br><b>b)</b> El consumidor paga el 21 % dels 6 000 €.<br><br><b>c)</b> Compara aquest IVA amb el preu final que paga el consumidor.',
  'apl-ud2/U2.36': 'Repassa quina és la fórmula de l\'interès <b>simple</b>.<br>Fixa\'t que dos anys i mig són 2,5 anys.',
  'apl-ud2/U2.37': 'Els 2 346 € que et tornen són el capital més els interessos. Anomenem <i>C</i> el capital: els interessos són <i>C</i> · 0,045 · 2, i per tant tenim aquesta equació:<br><i>C</i> + <i>C</i> · 0,045 · 2 = 2 346',
  'apl-ud2/U2.38': 'En primer lloc, calcula els interessos: el que torna menys el que va demanar.<br>Posteriorment, fes servir la fórmula de l\'interès simple, on ara la incògnita és el rèdit, que és el tant per u (i no el %).',
  'apl-ud2/U2.39': 'Fes servir la fórmula de l\'interès simple: ara coneixes l\'interès (225 €), el capital (3 000 €) i el rèdit (3 % = 0,03), i la incògnita és el temps.',
  'apl-ud2/2.5.1': 'Repassa quina és la fórmula per a un préstec amb interès <b>simple</b>.<br>Recorda que un 6 % es representa com 0,06.',
  'apl-ud2/2.5.2': 'En primer lloc, calcula <b>l\'interès</b>. Després, pots calcular les altres dades:<br>- <b>el total</b> es calcula amb una suma: cal sumar el capital inicial més els interessos<br>- <b>la quota mensual</b> és aquest total que has obtingut, però repartit entre tots els mesos que hi ha en 2 anys.',
  'apl-ud2/2.5.3': 'En primer lloc, calcula el <b>total</b>: la suma de totes les quotes.<br>Després, el <b>sobrecost</b>: el que pagues de més respecte al preu que haguessis pagat al comptat.',
  'apl-ud2/2.5.4': 'És veritat que cal multiplicar el capital pel rèdit en tant per u.<br>Però fixa\'t en el resultat: 50 € és l\'interès d\'un any. Tu creus que en dos anys et donen la mateixa quantitat?',
  'apl-ud2/2.5.5': 'Calcula el que pagues en total amb cada opció i compara-ho.<br>Per decidir si val la pena, pensa també en la teva situació: tens els diners ara? Necessites l\'ordinador ja?',
  'apl-ud2/2.6.1': 'El cost total és tot el que pagues: l\'entrada (si és que n\'hi ha), més totes les quotes.',
  'apl-ud2/2.6.2': 'Calcula el cost total de cada opció:<br>- <b>al comptat</b>: 400 €;<br>- <b>a terminis</b>: l\'entrada més les nou quotes.<br>Et demanen el «sobrecost»: això vol dir la diferència entre els dos preus obtinguts.',
  'apl-ud2/2.6.3': 'Per comparar, no miris la quota: calcula el cost total de cada opció.',
  'apl-ud2/2.6.4': 'És veritat que la quota de C és la més petita.<br>Però fixa\'t en el cost total que has calculat a l\'exercici anterior: quina opció és la més cara?<br>Segurament el company s\'ha oblidat de comptar quants mesos paga.',
  'apl-ud2/U2.94': '<b>a)</b> Els 300 € són el 0,8 % de les vendes: tens una situació de proporció directa.<br><br><b>b)</b> «Per mil» vol dir «de cada 1 000», igual que «per cent» vol dir «de cada 100». Per exemple, el 7,5‰ és 0,0075, perquè és el 7,5 per cada 1 000.',
  'apl-ud2/U2.FN': 'Si no saps com començar, prova-ho amb un preu concret que et resulti fàcil, com per exemple 100 €:<br>- al gener, apuja\'l un 10 %;<br>- al febrer, apuja un 10 % sobre el nou preu;<br>- al març, torna\'l a apujar un 10 %.<br><br>A partir dels 100 €, quin ha estat el preu final? Et sorprèn que el preu final sigui <b>superior a</b> 130 €?<br>Creus realment que els percentatges encadenats es poden sumar?',

  /* ── 4t ESO Aplicades · Unitat 3 · Proporcionalitat i escales ── */
  'apl-ud3/U2.48': 'Entre les persones i el salmó hi ha <b>proporció directa</b>. Si no saps com començar, pensa primer quant salmó correspon a una sola persona.',
  'apl-ud3/U2.59': 'Si no saps com començar, pensa-ho en un cas més senzill.<br>Imagina que tens només 4 pals (separats 15 m entre si). I fes-ho més fàcil: si estiguessin a 30 m de separació, estàs d\'acord que calen menys pals? Com trobaries la distància entre les dues poblacions?',
  'apl-ud3/U5.28': 'Una escala 1:75 vol dir que cada longitud del futbolí és 75 vegades més petita que la real.<br>- En primer lloc, calcula les dimensions del futbolí.<br>- Posteriorment, calcula la seva àrea.',
  'apl-ud3/U5.34': '<b>a)</b> Amb una raó de semblança de 1/100, cada longitud del futbolí és la centèsima part de la real: 1 cm de futbolí són 100 cm = 1 m del camp de futbol real.<br><br><b>b)</b> Calcula l\'àrea amb les mesures del futbolí. Quantes vegades és més petita aquesta àrea que la del camp real?',
  'apl-ud3/U5.67': 'Una escala 1:400 000 vol dir que 1 cm del mapa són 400 000 cm de la realitat.<br><br><b>a)</b> Aplica l\'escala i obtindràs un resultat que serà un nombre enorme, però expressat en centímetres. Per tant, com a pas final, has de passar el resultat a quilòmetres.<br><br><b>b)</b> Et recomanem que, abans de res, passis primer els 236 quilòmetres a centímetres.<br>Després, aplica l\'escala, però planteja bé l\'equació a partir de la proporció directa.',
  'apl-ud3/U5.69': 'Galícia fa uns 200 km d\'oest a est i uns 210 km de nord a sud, i un full DIN A4 fa 21 × 29,7 cm.<br>Prova diverses escales i calcula quant faria Galícia al paper: et sortiran nombres enormes en centímetres, i els hauràs de comparar amb la mida del full. Fes el mateix amb un post-it de 10 × 10 cm.',

  /* ── 4t ESO Aplicades · Unitat 4 · Mesura indirecta ── */
  'apl-ud4/4.1.2': 'Dos triangles són <b>semblants</b> quan tenen la mateixa forma. Per exemple, això passa quan fem una fotocòpia ampliada d\'un triangle.<br>La <b>raó de semblança</b> <i>k</i> = 3 ens diu quantes vegades és més llarg cada costat del triangle gran que el costat corresponent del petit.<br>Per exemple, quan fas una fotocòpia amb un 20 % d\'augment, llavors <i>k</i> = 1,2.',
  'apl-ud4/4.1.3': 'Els raigs del sol arriben al pal amb la mateixa inclinació que a l\'arbre (sempre que sigui al mateix instant, és clar). Per això, es formen dos triangles <b>semblants</b>: un triangle amb el pal i la seva ombra, i l\'altre triangle amb l\'arbre i la seva ombra.<br>A partir d\'aquí, podem escriure una equació, perquè hi ha proporció directa, i podem trobar el que ens demanen.',
  'apl-ud4/4.1.5': 'És veritat que l\'ombra de l\'arbre fa 3,9 m més que l\'ombra del pal, però això no es trasllada a l\'arbre i al pal.<br>Per exemple, imagina que són les 12 h del migdia i el sol és gairebé a dalt de tot, i l\'ombra de l\'arbre fa 1,25 m i l\'ombra del pal fa 1,2 m. Tu creus que l\'arbre només farà 0,05 m més d\'altura?',
  'apl-ud4/U5.57': 'Quan multipliquem tots els costats d\'un triangle per un mateix nombre <i>k</i>, obtenim un triangle <b>semblant</b>, i <i>k</i> és la <b>raó de semblança</b>.<br><br><b>a)</b> i <b>b)</b> Multiplica cada costat pel valor de <i>k</i> que et donen. Recorda que multiplicar per 1/2 és el mateix que dividir entre 2.<br><br><b>c)</b> Pensa amb lògica: dels dos triangles que has obtingut, un és el doble de l\'original, i l\'altre és la meitat de l\'original. Quant creus que val la raó de semblança <i>k</i>?',
  'apl-ud4/U5.64': 'Multiplica cada un dels tres costats per la <b>raó de semblança</b>, <i>r</i> = 1,6.<br>Com que 1,6 és més gran que 1, el triangle nou és més gran que l\'original. Si estiguessis fent una fotocòpia ampliada, posaries l\'ampliació del 60 %.',
  'apl-ud4/4.2.1': 'En dos triangles semblants, la raó de semblança s\'aplica a <b>tots</b> els costats: cada costat del triangle gran és el costat corresponent del petit multiplicat per <i>k</i> = 2.',
  'apl-ud4/4.2.2': 'El pal i la torre formen, amb les seves ombres, dos triangles rectangles <b>semblants</b>. Per tant, podem aplicar una situació de proporció directa: escriu la igualtat entre les dues fraccions, resol una equació i troba <i>h</i> com a altura de la torre.',
  'apl-ud4/4.2.4': 'El mirall fa que es formin dos triangles <b>semblants</b>: un amb tu i la teva distància fins al mirall, i l\'altre amb l\'arbre i la seva distància fins al mirall (la llum surt del mirall amb la mateixa inclinació amb què hi arriba).<br>Com que tenim una proporció directa, has de plantejar l\'equació adequada i quan la resolguis podràs trobar l\'altura de l\'arbre.',
  'apl-ud4/4.2.5': 'Fixa\'t en el resultat: el pal fa 2 m i la seva ombra, 1,5 m, és a dir, el pal és més alt que la seva ombra. Tu creus que la torre pot fer 9 m si la seva ombra en fa 12?<br>Segurament el company no ha escrit correctament la proporció.',
  'apl-ud4/4.2.7': 'Fes un dibuix amb totes les dades:<br>- l\'arbre <i>T</i><br>- les estaques <i>A</i>, <i>B</i> i <i>C</i><br>- el punt on t\'atures, que anomenem <i>D</i>.<br>Hi veuràs dos triangles <b>semblants</b> que tenen en comú el vèrtex <i>B</i>: <i>TAB</i> i <i>DCB</i>. Tots dos tenen un angle recte, i els angles que fan a <i>B</i> són iguals, perquè són <b>oposats pel vèrtex</b>.<br>A partir d\'aquí, hi ha proporció directa. Escriu l\'equació que correspon. Quin costat del triangle petit es correspon amb l\'amplada del riu?',
  'apl-ud4/U5.81': 'El fanal i l\'edifici, cadascun amb la seva ombra, formen dos triangles <b>semblants</b>, perquè en el mateix moment el sol arriba amb la mateixa inclinació a tots dos.<br>Per tant, entre l\'altura i l\'ombra hi ha proporció directa: podem escriure una equació i trobar l\'altura de l\'edifici.',
  'apl-ud4/U5.65': 'Si tots els costats es fan <i>k</i> vegades més llargs, el perímetre també es fa <i>k</i> vegades més llarg.<br>Per tant, calcula el perímetre del triangle de 7, 8 i 10 cm i compara\'l amb 125 cm: així obtindràs la <b>raó de semblança</b>. Finalment, amb el valor de <i>k</i>, podràs trobar els costats del triangle gran.',
  'apl-ud4/4.3.1': 'Recorda el <b>teorema de Pitàgores</b>, que relaciona els dos catets i la hipotenusa d\'un triangle rectangle.<br><br><b>a)</b> Et donen els dos catets i et demanen la hipotenusa.<br><br><b>b)</b> Ara la incògnita és un catet, i l\'has de trobar a partir de la hipotenusa i l\'altre catet.',
  'apl-ud4/4.3.2': 'L\'escala, la paret i el terra formen un <b>triangle rectangle</b>, perquè la paret és perpendicular al terra. Per tant, podem aplicar el teorema de Pitàgores.<br>Fes un esquema i pensa en primer lloc quin dels tres costats és la hipotenusa.',
  'apl-ud4/4.3.6': 'És veritat que l\'escala, la paret i el terra formen un triangle rectangle i que cal aplicar el teorema de Pitàgores.<br>Però fixa\'t en el resultat: l\'escala fa 5 m. Tu creus que, recolzada a la paret, pot arribar a 5,8 m d\'altura?',
  'apl-ud4/4.3.3': 'Fes un esquema del camp i traça-hi la diagonal: hi veuràs dos <b>triangles rectangles</b>. Per tant, podem aplicar el teorema de Pitàgores.',
  'apl-ud4/4.3.4': 'La torre, el terra i el cable formen un <b>triangle rectangle</b>, perquè la torre és perpendicular al terra. Fes un esquema i podràs aplicar el teorema de Pitàgores per trobar la llargada del cable.',
  'apl-ud4/4.3.7': 'Pensa què pots mesurar sense enfilar-te al pal:<br>- Amb les ombres, necessites un dia de sol, un objecte de referència i una cinta mètrica.<br>- Amb el teorema de Pitàgores, necessites un triangle rectangle on puguis mesurar dos costats.<br><br>Quins costats d\'un triangle rectangle podries mesurar en aquest cas?',
  'apl-ud4/4.4.1': 'Fes un esquema de cada situació i pregunta\'t:<br>- Hi ha dos objectes amb les seves ombres? Llavors hi ha triangles semblants i proporció directa.<br>- Hi ha un sol triangle rectangle amb dos costats coneguts? Llavors podem aplicar el teorema de Pitàgores.',
  'apl-ud4/4.4.3': 'És veritat que el pal, el terra i el cable formen un triangle rectangle i que cal aplicar el teorema de Pitàgores.<br>Però fixa\'t en el resultat: el cable fa 6 m i va del cim del pal fins al terra. Tu creus que el pal pot fer 6,3 m?<br>Segurament s\'ha equivocat en decidir quin costat és la hipotenusa.',
  'apl-ud4/4.4.4': 'Per a cada cas, pensa què pots mesurar de veritat, amb una cinta mètrica i sense mullar-te:<br>- La semblança (proporció directa) ens permet calcular una distància que no podem tocar, a partir d\'un triangle petit que sí que podem mesurar.<br>- El teorema de Pitàgores necessita un triangle rectangle amb dos costats que puguem mesurar.<br><br>Al riu, quin costat del triangle no podries mesurar mai?',
  'apl-ud4/U5.77': 'Fes un esquema i fixa\'t en els dos cables per separat. Anomenem <i>n</i> i <i>m</i> les dues distàncies horitzontals, com al dibuix:<br>- El cable que va de <i>B</i> a <i>C</i> forma un triangle gran amb la columna <i>AB</i> i un de petit amb l\'altura <i>h</i>: són <b>semblants</b>, i hi ha proporció directa.<br>- Fes el mateix amb el cable que va de <i>D</i> a <i>A</i> i la columna <i>CD</i>.<br><br>Obtindràs dues equacions. Si les combines bé, <i>n</i> i <i>m</i> desapareixen: l\'altura <i>h</i> només dependrà de <i>AB</i> i <i>CD</i>.',

  /* ── 4t ESO Aplicades · Unitat 11 · Idea de polinomi ── */
  'apl-ud11/AP.1': 'Restar un polinomi és sumar el seu oposat: canvia el signe de <b>tots</b> els termes del segon parèntesi.<br>Després, agrupa els termes del mateix grau.',
  'apl-ud11/AP.36': 'Sabem que, si substituïm la <i>x</i> per −3, el càlcul ha de donar −1.<br>D\'aquesta manera obtindràs una equació on l\'única incògnita és <i>a</i>.',
  'apl-ud11/AP.71': 'Fes un esquema de la pàgina amb els marges. Anomenem <i>x</i> l\'amplada de la pàgina: llavors, l\'altura és el doble, o sigui, 2<i>x</i>.<br><br><b>a)</b> Escriu la superfície de la pàgina en funció de <i>x</i>.<br><br><b>b)</b> La part útil també és un rectangle. Pensa quants centímetres li treuen els marges a l\'amplada i quants a l\'altura.',
  'apl-ud11/AP.76': '<b>a)</b> El signe menys afecta <b>tots</b> els termes de <i>G(x)</i>.<br><br><b>b)</b> Una vegada hagis fet l\'apartat anterior, serà senzill substituir 365 a <i>B(x)</i>.',
  'apl-ud11/AP.81': '<b>a)</b> Quan comença la festa encara no ha arribat cap assistent, i al local només hi ha l\'organització. Quin valor té <i>t</i> en aquell moment?<br><br><b>b)</b> L\'enunciat ja et diu quan hi va haver més gent.<br><br><b>c)</b> <b>Atenció</b>: una hora i mitja s\'expressa així: <i>t</i> = 1,5.',

  /* ── 4t ESO Aplicades · Unitat 5 · Equacions de 2n grau ── */
  'apl-ud5/U3.3': 'Substitueix <i>x</i> = 3 i <i>x</i> = −3 a cada equació i comprova si es compleix la igualtat.',
  'apl-ud5/U3.33': 'No cal que resolguis les equacions: pots fer-ho al revés i substituir les solucions de la llista a cada equació, per veure quines la compleixen.<br>Recorda que una equació de segon grau pot tenir dues solucions, una o cap.',
  'apl-ud5/U3.8': 'Són equacions de segon grau <b>incompletes</b>, sense terme en <i>x</i>. Per resoldre-les, troba en primer lloc quant val <i>x</i>² i posteriorment fes l\'arrel quadrada.<br><br><b>Atenció</b>: un nombre positiu té dues arrels quadrades, una de positiva i una de negativa.',
  'apl-ud5/U3.38': 'Per exemple, en el primer cas, la igualtat a zero només és certa en aquests casos: o bé <i>x</i> = 0, o bé (6<i>x</i> - 7) = 0.<br>A partir d\'aquí, trobaràs dues solucions.',
  'apl-ud5/U3.39': 'En general, pots aplicar la propietat distributiva, igualar-ho tot a zero i resoldre l\'equació de segon grau.<br>L\'apartat <b>a)</b> es pot resoldre més ràpidament, saps per què?',
  'apl-ud5/AP.49': '<b>a)</b> i <b>b)</b> Són <b>igualtats notables</b>: el quadrat d\'una suma i el quadrat d\'una diferència.<br><br><b>c)</b> Et donem una pista: <i>(2x − 3)³</i> = <i>(2x − 3)² · (2x − 3)</i>.',
  'apl-ud5/AP.10': 'Identifica quina <b>igualtat notable</b> és cada producte:<br>- el <b>quadrat d\'una suma</b>;<br>- el <b>quadrat d\'una diferència</b>;<br>- <b>suma per diferència</b>.',
  'apl-ud5/U3.37': 'Passa-ho tot a l\'esquerra fins que l\'equació tingui aquesta forma:<br><i>ax</i>² + <i>bx</i> + <i>c</i> = 0<br>Per exemple, a l\'apartat b) obtens <i>x</i>² − 4<i>x</i> + 3 = 0.<br>Posteriorment, aplica la <b>fórmula de l\'equació de segon grau</b>.',
  'apl-ud5/U3.9': 'No cal resoldre-les: n\'hi ha prou de calcular el <b>discriminant</b>, <i>b</i>² − 4<i>ac</i>, que és el que hi ha dins de l\'arrel de la fórmula:<br>- Si és positiu, l\'equació té dues solucions.<br>- Si és zero, en té una (<b>solució doble</b>).<br>- Si és negatiu, no en té cap, perquè no existeix l\'arrel quadrada d\'un nombre negatiu.',
  'apl-ud5/U3.45': 'Calcula el <b>discriminant</b> de cada equació, que vol dir: <i>b</i>² − 4<i>ac</i>.<br>Pista extra: en alguns casos es pot fer per lògica. Per exemple, a −<i>x</i>² = 5, pensa si un quadrat pot ser negatiu.',
  'apl-ud5/U3.7': 'Et donem una pista: l\'equació <i>(x − p)(x − q)</i> = 0 té com a solucions els nombres <i>p</i> i <i>q</i>.',
  'apl-ud5/U3.11': 'Et donem una pista: l\'equació (<i>x</i> - 3) · (<i>x</i> + 5) = 0 té solucions <i>x</i> = 3 i <i>x</i> = -5.<br>Una altra pista: l\'equació 6 · (<i>x</i> - 3) · (<i>x</i> + 5) = 0 té exactament les mateixes solucions.',
  'apl-ud5/U3.40': '<b>a)</b> Si passes el 4 a l\'altre membre, obtens (<i>x</i> - 3)² = 4.<br>Quins nombres elevats al quadrat donen 4?<br><br><b>b)</b> Et donem una pista: <i>x</i>² − 6<i>x</i> + 8 = (<i>x</i> − 3)² − 1.',
  'apl-ud5/U3.41': 'Primer desenvolupa els productes i els quadrats de cada membre, aplicant la propietat distributiva.<br>Després, passa-ho tot a un membre i agrupa els termes semblants fins que l\'equació tingui aquesta forma:<br><i>ax</i>² + <i>bx</i> + <i>c</i> = 0.',
  'apl-ud5/U3.42': 'Per saber realment quin és el grau d\'una equació cal, en primer lloc, desenvolupar-ho tot i simplificar-ho, perquè podria passar que els termes en <i>x</i>² s\'anul·lin i que finalment l\'equació sigui de primer grau.',
  'apl-ud5/U3.43': 'Multiplica els dos membres pel <b>mínim comú múltiple</b> dels denominadors. Per exemple, en el primer apartat has de multiplicar per 12.<br>D\'aquesta manera obtindràs una equació sense fraccions, que ja saps resoldre.',
  'apl-ud5/U3.49': 'Calcula el discriminant de <i>x</i>² + 2<i>x</i> + <i>c</i> = 0: obtindràs 4 − 4<i>c</i>, que només depèn de <i>c</i>.<br>Per tant, tria valors de <i>c</i> que facin que el discriminant sigui positiu, zero o negatiu.',
  'apl-ud5/U3.51': '- Si creus que una afirmació és vertadera, raona per què ho és.<br>- Si creus que és falsa, busca un contraexemple, és a dir, un cas concret on no es compleix.<br>Per exemple, a l\'apartat e), multiplica per 2 una equació que ja sàpigues resoldre i compara les solucions.',
  'apl-ud5/U3.63': 'Anomenem <i>x</i> el nombre de germans i germanes, comptant-te a tu.<br>Cada persona fa un regal a les altres menys a ella mateixa. Per tant, hi ha <i>x</i> − 1 regals que fa cada persona.<br>Amb això podràs escriure una equació de segon grau.',
  'apl-ud5/U3.71': 'Fes un esquema de l\'hort: els 70 m de cable són el <b>perímetre</b>. Anomenem <i>x</i> la llargada: llavors, l\'amplada és 3<i>x</i>/4.<br>- En primer lloc, calcula el perímetre en funció de la llargada i l\'amplada. Obtindràs una equació i podràs aïllar la incògnita <i>x</i>.<br>- Posteriorment, quan ja tinguis les mesures de l\'hort, calcula la seva àrea.',
  'apl-ud5/U3.77': 'Anomenem <i>x</i> l\'amplada del jardí: llavors, la llargada és <i>x</i> + 10. Amb l\'àrea obtens aquesta equació de segon grau:<br><i>x</i> · (<i>x</i> + 10) = 5 600<br><br>Pensa si les dues solucions que obtinguis realment tenen sentit per a aquest enunciat.',
  'apl-ud5/U7.94': 'La pilota surt de terra (és a dir, amb altura <i>h</i> = 0) i quan torna a terra, torna a tenir <i>h</i> = 0. Per tant, en primer lloc troba els dos moments <i>t</i> on <i>h(t)</i> = 0.<br>Com que la paràbola és simètrica, el punt més alt és just a la meitat.',
  'apl-ud5/U7.95': '<b>a)</b> Pensa en la forma que fa la pilota quan puja i baixa: és un tir parabòlic.<br><br><b>b)</b> Fes un esquema: posa el jugador a <i>x</i> = 0 i la cistella a <i>x</i> = 4,6. El punt més alt és a la meitat, és a dir, a <i>x</i> = 2,3, i a 3,5 m d\'altura: aquest és el <b>vèrtex</b> de la paràbola.<br>Una paràbola es pot escriure a partir del vèrtex (<i>p</i>, <i>q</i>) d\'aquesta manera:<br><i>y = a(x − p)² + q</i>.',
  'apl-ud5/U3.44': 'Sabem que, si substituïm <i>x</i> = √2 − 1, l\'equació es compleix. D\'aquesta manera obtindràs una equació de primer grau on l\'única incògnita és <i>a</i>.<br>Per fer el quadrat (√2 − 1)², fes servir la igualtat notable del «quadrat d\'una resta».',

  /* ── 4t ESO Aplicades · Unitat 10 · Sistemes d’equacions i inequacions ── */
  'apl-ud10/U4.24': 'Substitueix <i>x</i> = 2 i <i>y</i> = −1 a cada equació i comprova si es compleix la igualtat.<br>Per exemple, a l\'apartat a): 2 + 3 · (−1) = −1, que no és 5. Per tant, en aquest cas la igualtat no es compleix.',
  'apl-ud10/U4.26': 'Substitueix cada possibilitat a l\'equació i comprova si es compleix la igualtat.',
  'apl-ud10/U4.32': 'En primer lloc, ordena les equacions perquè la <i>x</i>, la <i>y</i> i el terme independent estiguin al mateix lloc. Posteriorment, compara-les:<br>- Si una és l\'altra multiplicada per un nombre, són la mateixa recta: <b>sistema compatible indeterminat</b>.<br>- Si els coeficients de <i>x</i> i <i>y</i> són proporcionals però el terme independent no, són rectes paral·leles: <b>sistema incompatible</b>.<br>- Si no, les rectes es tallen en un punt: <b>sistema compatible determinat</b>.',
  'apl-ud10/U4.39': 'En primer lloc, treu els denominadors: multiplica cada equació pel mínim comú múltiple dels seus denominadors. Per exemple, la primera equació de l\'apartat a) l\'has de multiplicar per 4.<br>Posteriorment, resol el sistema pel mètode que prefereixis.',
  'apl-ud10/U4.8': 'Has de resoldre cada sistema tres vegades, una per mètode:<br>- <b>Substitució</b>: aïlla una incògnita d\'una equació i substitueix-la a l\'altra.<br>- <b>Igualació</b>: aïlla la mateixa incògnita de les dues equacions i iguala les expressions.<br>- <b>Reducció</b>: multiplica les equacions per nombres adequats perquè, en sumar-les o restar-les, desaparegui una incògnita.',
  'apl-ud10/U4.63': 'Anomenem <i>x</i> el nombre d\'homes i <i>y</i> el de dones. Cada frase de l\'enunciat et dona una equació:<br>- el <b>total de persones</b>: <i>x</i> + <i>y</i> = 60;<br>- la <b>situació imaginada</b>: si marxen 3 homes i en vénen 3 dones, queden <i>x</i> − 3 homes i <i>y</i> + 3 dones, i les dones són la tercera part dels homes (o potser et convé pensar-ho com que «els homes són el triple que les dones»).',
  'apl-ud10/U4.64': 'Anomenem <i>x</i> el nombre de camells i <i>y</i> el de dromedaris. Escriu dues equacions:<br>- una amb les <b>potes</b> (tots dos animals en tenen 4);<br>- una altra amb les <b>gepes</b> (els camells en tenen 2 i els dromedaris, 1).<br>Així obtindràs un <b>sistema d\'equacions</b>.',
  'apl-ud10/U4.68': 'Anomenem <i>x</i> el nombre de monedes de 0,50 € i <i>y</i> el de monedes de 0,20 €. Escriu dues equacions:<br>- una amb el <b>nombre de monedes</b> (n\'hi ha 8);<br>- una altra amb els <b>diners</b> (en total, 3,10 €).',
  'apl-ud10/U3.58': 'Substitueix <i>x</i> = 2 a cada costat i compara els dos nombres que obtens.<br>Per exemple, a l\'apartat a): 2 · 2 = 4, i 4 és més gran que 3. Per tant, en aquest cas faràs servir >.',
  'apl-ud10/U3.24': 'Resol-les com una equació: passa les <i>x</i> a un membre i els nombres a l\'altre.<br><br><b>Atenció</b>: si multipliques o divideixes els dos membres per un nombre negatiu, el sentit de la desigualtat canvia. Per exemple, 2 és més petit que 3, però −2 és més gran que −3.',
  'apl-ud10/U3.59': 'En primer lloc, elimina els parèntesis aplicant la propietat distributiva, i agrupa els termes semblants.<br>Posteriorment, resol la inequació que obtinguis.',
  'apl-ud10/U3.26': 'Et donem una pista: la solució [2, +∞) vol dir que <i>x</i> pot ser 2 o qualsevol nombre més gran, és a dir, <i>x</i> ≥ 2.<br>A partir d\'aquí, suma, resta o multiplica els dos membres pel mateix nombre (positiu) i ja tindràs una inequació diferent amb la mateixa solució.',
  'apl-ud10/U3.80': 'Són dues inequacions alhora: <i>x</i> − 3 ha de ser més gran que 0 i, també, més petit que 18.<br>Pots resoldre-les per separat.',
  'apl-ud10/U3.73': 'Anomenem <i>x</i> el nombre d\'hores. Escriu què costa cada opció:<br>- la <b>cadira</b>: 3 € per hora, és a dir, 3<i>x</i>;<br>- la <b>gandula</b>: 5 € fixos més 2 € per hora.<br>«Més econòmica» vol dir que la gandula costa menys que la cadira: això et dona una <b>inequació</b>, perquè faràs servir el signe «menor que».',
  'apl-ud10/U7.93': 'Escriu el preu de cada tarifa en funció del nombre de dies, <i>x</i>:<br>- <b>tarifa A</b>: 50 € fixos més 10 € per dia;<br>- <b>tarifa B</b>: 30 € fixos més 12 € per dia.<br><br><b>a)</b> i <b>b)</b> Substitueix el nombre de dies a les dues funcions i compara.<br><br><b>c)</b> El punt on es tallen les dues rectes ens indica el dia en què les dues tarifes costen el mateix.',

  /* ── 4t ESO Aplicades · Unitat 6 · La paràbola ── */
  'apl-ud6/U7.QS1': 'Fixa\'t en la forma del polinomi, que és una <b>igualtat notable</b>: el quadrat d\'una diferència. Per tant, l\'equació es pot escriure com (<i>x</i> − 1)² = 0.',
  'apl-ud6/U6.24': '- Tall amb l\'eix <i>Y</i>: calcula la imatge de <i>x</i> = 0.<br>- Tall amb l\'eix <i>X</i>: iguala la funció a 0. Per exemple, a l\'apartat a) obtens <i>x</i>² − 3<i>x</i> = 0, i pots treure factor comú per resoldre-la, o bé fer servir la fórmula per resoldre l\'equació de segon grau.',
  'apl-ud6/U7.46': 'Si la paràbola s\'escriu com <i>y = a(x − p)² + q</i>, el <b>vèrtex</b> és el punt (<i>p</i>, <i>q</i>), i el signe que tingui el valor <i>a</i> et diu si s\'obre cap amunt o cap avall.<br>Per exemple, a l\'apartat a), <i>y</i> = (<i>x</i> + 1)² − 1 té el vèrtex al punt (−1, −1) i s\'obre cap amunt.',
  'apl-ud6/U7.45': 'Fes una taula de valors amb <i>x</i> = −2, −1, 0, 1 i 2 i representa els punts obtinguts al pla cartesià.<br>Després, compara les tres paràboles: què canvia quan el coeficient de <i>x</i>² és negatiu?',
  'apl-ud6/U7.49': 'En primer lloc, troba el <b>vèrtex</b>: repassa quina és la fórmula de la primera coordenada, i recorda que per obtenir la segona coordenada del vèrtex només cal trobar la imatge de la primera coordenada amb la funció.<br>Posteriorment, mira el coeficient de <i>x</i>²:<br>- si és positiu, la paràbola s\'obre cap amunt i el vèrtex és un <b>mínim</b>;<br>- si és negatiu, s\'obre cap avall i el vèrtex és un <b>màxim</b>.',
  'apl-ud6/U7.51': 'En primer lloc, busca el vèrtex i els punts de tall amb l\'eix <i>X</i>. Posteriorment, completa-ho amb una taula de valors al voltant del vèrtex.<br>Fixa\'t que als apartats b) i d) la funció ja ve escrita a partir del vèrtex.',
  'apl-ud6/U6.28': 'Una fracció val zero només quan el numerador val zero. Per exemple, a l\'apartat a) has de resoldre <i>x</i>² + 4<i>x</i> + 3 = 0.',
  'apl-ud6/U7.54': '<b>a)</b> Escriu la paràbola a partir del vèrtex, <i>y = a(x − p)² + q</i>, i tria el valor d\'<i>a</i> que vulguis.<br><br><b>b)</b> Tria una paràbola qualsevol, per exemple <i>y = x² + c</i>: substitueix <i>x</i> = −1 i <i>y</i> = 4 i trobaràs el valor de <i>c</i>.',
  'apl-ud6/U7.86': 'El punt més alt del salt és el <b>vèrtex</b> de la paràbola, (4, 4).<br>Com que la paràbola és simètrica, el punt de sortida és a la mateixa distància del vèrtex que el punt on cau sobre l\'enemic.',
  'apl-ud6/U7.106': '<b>a)</b> La funció és una paràbola cap avall (el motiu és que el coeficient que multiplica la <i>x</i>² és negatiu). Com que la paràbola mira cap avall, sabem que el cost més alt serà justament al <b>vèrtex</b>.<br><br><b>b)</b> Substitueix <i>x</i> = 15. <b>Atenció</b>: recorda que el resultat és en milers d\'euros.',
  'apl-ud6/U7.96': 'El xoc passa on les dues trajectòries tenen el mateix punt: iguala les dues expressions.<br>Obtindràs una equació de segon grau. Quantes solucions té? Pensa què vol dir cadascuna.',
  'apl-ud6/U7.100': 'Et demanen l\'altura en funció de la velocitat: aïlla <i>h</i> de la fórmula <i>v</i> = √(20<i>h</i>), elevant els dos membres al quadrat.<br>Obtindràs una paràbola. <b>Atenció</b>: fes la taula de valors només amb velocitats positives.',

  /* ── 4t ESO Aplicades · Unitat 7 · Funcions: llegim gràfics ── */
  'apl-ud7/U6.7': '<b>a)</b> «La quarta part» d\'un nombre és <i>x</i> dividit entre 4.<br><br><b>b)</b> Tria valors de <i>x</i> que siguin múltiples de 4: les imatges sortiran enteres.<br><br><b>c)</b> L\'enunciat parla de nombres <b>enters</b>. Hi ha algun nombre enter entre 1 i 2?',
  'apl-ud7/U6.52': 'Substitueix cada valor a la funció.<br><b>Atenció</b>: quan substitueixes nombres negatius, recorda escriure\'ls entre parèntesis: (−2)² = 4, i (−2)³ = −8.',
  'apl-ud7/U6.79': 'Llegeix la gràfica d\'esquerra a dreta, com si hi caminessis per sobre:<br>- si puja, la funció és <b>creixent</b>; si baixa, <b>decreixent</b>;<br>- els punts on passa de pujar a baixar són <b>màxims</b>, i els punts on passa de baixar a pujar són <b>mínims</b>.',
  'apl-ud7/U6.84': 'Busca el punt més alt i el més baix de la gràfica i llegeix a quina hora correspon cada valor.<br>Un màxim és <b>absolut</b> si és el valor més alt de tot el dia. En canvi, tenim un màxim <b>relatiu</b> si només ho és comparat amb els punts del seu voltant.',
  'apl-ud7/U6.89': 'Fes servir la fórmula de l\'enunciat:<br>- en primer lloc, calcula <i>f</i>(−1) i <i>f</i>(2);<br>- posteriorment, resta\'ls i divideix el que obtinguis entre el valor inicial, <i>f</i>(−1).',
  'apl-ud7/U6.100': 'La funció és <b>definida a trossos</b>: dibuixa cada tros només a l\'interval que li correspon.<br>Als punts de canvi, <i>x</i> = 1 i <i>x</i> = 3, mira quin tros inclou el punt (punt ple) i quin no (punt buit).',
  'apl-ud7/U6.112': 'La nostra funció serà <i>f(x)</i>, on anomenem <i>x</i> l\'import de la comanda.<br>Cada frase de l\'enunciat és un tros de la funció: escriu què costa l\'enviament i segons els valors de <i>x</i>.',
  'apl-ud7/U7.87': 'Fes la taula amb uns quants consums, per exemple 0 kWh, 100 kWh i 200 kWh: l\'import és la part fixa (10 €) més el que costen els kWh.<br>Amb la taula, veuràs quina expressió segueix: és una funció <b>afí</b>.',
  'apl-ud7/U7.89': 'El preu és una part fixa (la baixada de bandera, 1 €) més una part que depèn dels quilòmetres (0,80 € per quilòmetre).',
  'apl-ud7/U7.92': '<b>a)</b> Per exemple, si hi van 10 alumnes, cadascun ha de vendre 36 capses. I si hi van 20 alumnes?<br><br><b>b)</b> Pensa quina operació has fet per omplir la taula: és una funció de <b>proporcionalitat inversa</b>.<br><br><b>c)</b> Multiplica les dues columnes de la taula, fila a fila.',
  'apl-ud7/U2.44': 'Calcula els diners obtinguts de les dues maneres:<br>- amb <b>interès simple</b>, cada any guanyes el 4 % dels 1 000 € inicials;<br>- amb <b>interès compost</b>, cada any guanyes el 4 % del que tens, que ja inclou els interessos dels anys anteriors. Pots fer servir el <b>factor multiplicador</b> 1,04.',
  'apl-ud7/U7.97': 'Comença amb 1 bacteri i fes una taula: cada 25 minuts, el nombre de bacteris es multiplica per 2 (1, 2, 4, 8…). Per tant, és una funció <b>exponencial</b> de base 2.',
  'apl-ud7/U7.75': 'Escriu cada funció com una potència de la forma <i>aˣ</i>, amb les propietats de les potències.<br>Per exemple, 3²ˣ = 9ˣ.<br>Posteriorment, fes una taula de valors amb <i>x</i> = −2, −1, 0, 1 i 2.',

  /* ── 4t ESO Aplicades · Unitat 8 · Estadística ── */
  'apl-ud8/U8.1': 'Fem servir una <b>mostra</b> quan no podem estudiar tota la <b>població</b>. Pensa en cada cas: creus realment que els pots mesurar tots?',
  'apl-ud8/U8.2': 'Compta quantes vegades surt cada color: aquesta és la <b>freqüència absoluta</b>.<br>En canvi, la <b>freqüència relativa</b> és la freqüència absoluta dividida pel total de dades (que en aquest cas és 15).',
  'apl-ud8/U8.3': 'Fes la taula de freqüències comptant quants nens i quantes nenes hi ha.<br>Per al <b>diagrama de sectors</b>, l\'angle de cada sector i la freqüència estan en proporció directa: tot el cercle (que són 360°) correspon al total de 20 nadons.',
  'apl-ud8/U8.34': '<b>a)</b> Ordena els valors possibles, de 0 a 5, i compta quantes vegades surt cadascun. Busca als teus apunts què significa la <b>freqüència acumulada</b> d\'un valor.<br><br><b>b)</b> Per exemple, què vol dir la freqüència acumulada del valor 2?',
  'apl-ud8/U8.39': '<b>a)</b> Passa cada percentatge a nombre d\'estudiants. Per exemple, el 10 % de 30 són 3 estudiants.<br><br><b>b)</b> «Menys de dues» vol dir «zero» o «una».',
  'apl-ud8/U8.40': 'El 15 % del nombre d\'estudiants ha de ser un nombre enter (no hi pot haver mitja persona esquerrana).<br>Escriu el 15 % com una fracció, 15/100, i simplifica-la. Què et diu el denominador?',
  'apl-ud8/U8.46': 'Com que en total hi ha 35 dades, <i>f</i>₅ és el que falta per arribar a 35.<br>La variable és quantitativa i només té cinc valors: pensa quin gràfic fas servir en aquests casos.',
  'apl-ud8/U8.49': 'L\'angle de cada sector i la freqüència estan en proporció directa: els 360° del cercle corresponen al total.<br>Per exemple, la pasta té <i>h</i>ᵢ = 0,225, i per tant el seu angle es calcula així: 0,225 · 360°.',
  'apl-ud8/U8.52': 'En primer lloc, fes els intervals: [150, 155), [155, 160)…, de manera que hi puguis classificar totes les dades. Posteriorment, compta les dades que conté cada interval.<br><br><b>Atenció</b>: l\'interval [150, 155) inclou el 150 però no el 155.',
  'apl-ud8/U8.54': 'És un <b>histograma</b>: cada barra és un interval, i la seva alçada és la freqüència absoluta d\'aquell interval. Per exemple, a l\'interval [0, 5) hi ha 7 dades.',
  'apl-ud8/U8.6': 'Agrupa les dades en intervals, per exemple d\'amplitud 10 començant per [40, 50).<br><br><b>a)</b> Pensa quin gràfic es fa servir amb dades agrupades en intervals.<br><br><b>b)</b> Les <b>mesures de centralització</b> són la mitjana, la mediana i la moda.',
  'apl-ud8/U8.58': '- La <b>mitjana</b>: suma totes les dades i divideix entre el nombre de dades.<br>- La <b>mediana</b>: ordena les dades i agafa la del mig. Si n\'hi ha un nombre parell, no existeix «la posició que està al mig», i has de fer la mitjana aritmètica de les dues posicions que queden al mig.<br>Per exemple, al grup b) hi ha 15 dades: la mediana és la que ocupa la posició 8.<br>- La <b>moda</b>: la dada que es repeteix més vegades.',
  'apl-ud8/8.3.2': 'És una <b>mitjana ponderada</b>: cada nota compta segons el seu pes.<br>- Multiplica cada nota pel seu pes i suma-ho tot.<br>- Divideix per la suma dels pesos (que és 100).',
  'apl-ud8/8.3.4': 'La mitjana simple tracta les tres notes igual. Mira quina prova té més pes a l\'exercici 8.3.3 i quina nota hi ha tret l\'alumne.',
  'apl-ud8/8.3.5': 'Calcula la mitjana i també la mediana. Després, concentra\'t en el sou de 8 000 €: quina de les dues mesures canvia molt per «culpa» d\'aquest sou, i en canvi l\'altra gairebé no canvia?',
  'apl-ud8/8.3.6': 'És veritat que cal multiplicar cada nota pel seu pes i sumar.<br>Però fixa\'t en el resultat: tu creus que la mitjana de tres notes entre 5 i 8 pot sortir més gran que 8?<br>Segurament el company no ha dividit entre el nombre correcte.',
  'apl-ud8/U8.63': 'Hi ha 40 dades i només deu valors diferents, del 0 al 9: en primer lloc, fes una taula de freqüències.',
  'apl-ud8/U8.59': 'La mitjana és la suma de cada valor per la seva freqüència, dividida entre el nombre total de dades (que és la suma de les freqüències).<br>Escriu aquesta mitjana, amb <i>x</i>₄ com a incògnita, i iguala-la a 5: obtindràs una equació de primer grau.',
  'apl-ud8/U8.70': '- Si la mitjana dels 27 estudiants és 84, quant sumen totes les puntuacions de tots aquests estudiants?<br>- Troba també la suma de les puntuacions de 28 estudiants amb mitjana 83.<br>- Pensa una cosa: els 28 estudiants són l\'Ana i els 27 estudiants anteriors.',
  'apl-ud8/U8.62': 'Amb dades agrupades, cada interval es representa per la seva <b>marca de classe</b>, que és el punt mig de l\'interval. Per exemple, la marca de classe de [0, 4) és 2.',
  'apl-ud8/U8.69': 'Pensa amb lògica: ara mateix el 23 només surt una vegada. Si la moda ha de ser 23, quin valor ha de tenir la variable <i>x</i>?<br>Després, la condició que et diuen sobre la mitjana et permetrà trobar el valor de la variable <i>y</i>.',
  'apl-ud8/U8.89': '<b>La mitjana</b>: calcula la mitjana dels cinc dies. Quina distància ha de córrer dissabte perquè la mitjana sigui la mateixa?<br><br><b>La mediana</b>: ordena les cinc distàncies. Com que tens 6 dades i és un nombre parell, no existeix «la posició que està al mig». En aquests casos, per trobar la mediana has de fer la mitjana aritmètica de les dues posicions que queden al mig (en aquest cas, la 3a i la 4a posició).',
  'apl-ud8/8.3.8': 'Si la mitjana de les 6 notes és 7,5, quant han de sumar totes elles?<br>Una altra pista: pensa que aquesta suma són les cinc notes que ja coneixes, més la sisena que tu vols saber.',
  'apl-ud8/8.3.10': 'Anomenem <i>x</i> la nota de l\'examen. La nota final és una mitjana ponderada, i per tant tenim aquesta equació:<br>0,4 · <i>x</i> + 0,6 · 7 = 7,5',
  'apl-ud8/8.3.11': 'És veritat que cal fer una mitjana amb les dues classes.<br>Però pensa en un cas extrem: si la classe A tingués 1 alumne i la B en tingués 30, tu creus que la mitjana de tots seria 6,5?<br>Segurament el company no ha tingut en compte quants alumnes té cada classe.',
  'apl-ud8/U8.80': '<b>a)</b> La rentabilitat mitjana és la mitjana dels cinc percentatges, amb el seu signe.<br><br><b>b)</b> Cada any, els diners es multipliquen per un <b>factor multiplicador</b>. Per exemple, un +2,57 % és multiplicar per 1,0257, i un −0,22 % significa multiplicar per 0,9978.',
  'apl-ud8/U8.81': 'En primer lloc, fes una taula amb les cinc classes de pes i compta quantes coliflors hi ha a cadascuna.<br><br><b>a)</b> El que es cobra per una coliflor és el seu pes pel preu per quilo de la seva classe.<br><br><b>b)</b> Divideix els ingressos totals pel pes total.<br><br><b>c)</b> Calcula el pes mitjà de les coliflors de l\'hort.<br><br><b>d)</b> Mira la taula de l\'apartat a).<br><br><b>e)</b> Suma 0,4 kg a cada coliflor: algunes canviaran de classe.',
  'apl-ud8/U8.82': '- Si creus que una frase és vertadera, busca un cas més senzill (no cal que siguin 25 estudiants) on s\'entengui el teu raonament.<br>- Si creus que una frase és falsa, busca un contraexemple, és a dir, un cas on veiem clar per què és impossible.',
  'apl-ud8/U8.73': 'Ara hi ha 10 dades, i la mediana és la mitjana de la 5a i la 6a. Si n\'hi afegeixes dues, en tindràs 12, i les dues del mig seran la 6a i la 7a.',
  'apl-ud8/U8.77': '- Si la mitjana de 100 nombres és 86, quant sumen tots?<br>- Fes el mateix amb els 80 nombres que queden i la mitjana 84.<br><br>Una altra pista: pensa que els 100 nombres són els 80 que queden, més els 20 esborrats que tu vols saber.',

  /* ── 4t ESO Aplicades · Unitat 9 · Atzar i decisions ── */
  'apl-ud9/U9.17': 'Un experiment és <b>aleatori</b> si no pots saber el resultat abans de fer-lo. En canvi, és <b>determinista</b> si sempre dona el mateix resultat.',
  'apl-ud9/U9.63': 'Per a cada cas, pregunta\'t: «si repeteixo l\'experiència en les mateixes condicions, sempre obtinc el mateix resultat?»<br><br><b>Atenció</b>: compara bé els apartats g) i h), que s\'assemblen molt però no són el mateix.',
  'apl-ud9/U9.1': 'Fes un <b>diagrama d\'arbre</b>:<br>- en primer lloc, tria el color de la samarreta.<br>- per a cadascuna de les tries anteriors, escull el color dels pantalons.<br>- finalment, per tancar l\'arbre, has d\'escollir el color dels mitjons.',
  'apl-ud9/U9.2': 'Pensa quantes lletres pots posar a la primera posició; un cop posada, quantes lletres queden per a la segona posició, i així fins a l\'última posició.',
  'apl-ud9/U9.45': 'Fes un <b>diagrama d\'arbre</b>:<br>- en primer lloc, tria el primer plat;<br>- per a cadascun dels primers, tria el segon;<br>- finalment, per tancar l\'arbre, tria les postres.',
  'apl-ud9/U9.47': 'Calcula pas a pas:<br>- quantes opcions tens per a la primera xifra?<br>- quantes per a la segona?<br>- quantes per a la tercera?<br><br><b>Atenció</b>: les xifres es poden repetir. Per exemple, 211 també val.',
  'apl-ud9/U9.58': 'Cada persona encaixa la mà amb les altres 9. Però si multipliques 10 per 9, sortiran 90 encaixades, i això és massa. Per quin motiu?',
  'apl-ud9/U9.23': 'En primer lloc, troba quantes creus han sortit.<br><b>Atenció</b>: el total són 75 llançaments, no 100.<br>La <b>freqüència relativa</b> és el nombre de vegades que ha sortit dividit entre el nombre total de llançaments.',
  'apl-ud9/U9.26': 'Aplica la <b>regla de Laplace</b>: la probabilitat és el nombre de casos favorables dividit entre el nombre de casos possibles (que, en aquest cas, són 20 boles).',
  'apl-ud9/U9.27': 'Aplica la regla de Laplace. Per poder aplicar la fórmula, necessites saber quantes persones hi ha a l\'aula en total.',
  'apl-ud9/U9.28': 'Aplica la regla de Laplace: els casos possibles són totes les peces de roba (que en total són 20).<br><br><b>Atenció</b> a l\'apartat d): «una camisa» pot ser de màniga llarga o de màniga curta.',
  'apl-ud9/U9.80': 'Aplica la regla de Laplace amb les 40 cartes: per a cada apartat, compta quantes cartes compleixen la condició.',
  'apl-ud9/U9.81': 'Les probabilitats dels successos elementals han de complir dues condicions alhora:<br>1- Cadascuna ha de ser entre 0 i 1.<br>2- Entre totes han de sumar exactament 1.<br><br>Pensa si en el cas de l\'enunciat es compleixen les dues condicions.',
  'apl-ud9/U9.33': 'Fes una taula de doble entrada amb els resultats dels dos daus: 6 files i 6 columnes, 36 casos igual de probables. A cada casella, escriu la suma.',
  'apl-ud9/U9.40': 'Fes un diagrama d\'arbre de dues extraccions i escriu la probabilitat a cada branca:<br>- Si <b>no retornes la bola</b>, a la segona extracció només queden 3 boles.<br>- Si <b>tornes la bola</b>, a la segona extracció tenim 4 boles, és a dir, igual que a la primera.',
  'apl-ud9/U9.41': 'Fes l\'arbre de les tres monedes. Et sortiran 8 casos, tots ells igual de probables:<br>- CCC<br>- CCX<br>- CXC<br>…<br>Després, compta quants casos compleixen cada condició.',
  'apl-ud9/U9.99': 'Fes un arbre de dos nivells: el primer fill i el segon.<br><br><b>Atenció</b>: «un nen i una nena» es pot donar de dues maneres (nen-nena o nena-nen).',
  'apl-ud9/U9.88': 'Fes l\'arbre de les tres monedes. Et sortiran 8 casos, tots ells igual de probables.<br>- CCC<br>- CCX<br>- CXC<br>…',
  'apl-ud9/U9.93': 'Fes un arbre de dues extraccions. Les boles no es tornen a l\'urna: a la segona extracció ja no n\'hi ha 10, sinó que només en queden 9.',
  'apl-ud9/U9.43': 'Fes un diagrama d\'arbre amb les probabilitats:<br>- en primer lloc, vacunat (0,6) o no vacunat (0,4);<br>- per a cadascuna d\'aquestes branques, emmalaltit o no.',
  'apl-ud9/U9.87': 'En un dau, les sis cares sumen 21. Si el dau és sobre la taula, es veuen totes les cares menys la de sota.<br>Per tant, la suma de les cares visibles només depèn de la cara de sota: quins valors pot prendre aquesta suma? Fes les 6 possibilitats segons la cara que no es veu.',
  'apl-ud9/9.5.2': 'Un joc és <b>just</b> quan, de mitjana, ni guanyes ni perds. Calcula el guany mitjà:<br>- el que guanyes per la probabilitat de guanyar (1/6);<br>- menys el que perds per la probabilitat de perdre (5/6).',
  'apl-ud9/9.5.3': 'Fes el mateix càlcul que a l\'enunciat, però amb un premi de 36 € en lloc de 35 €.<br>Després, pensa per quin motiu les ruletes de debò paguen 35 € en lloc de pagar 36 €.',
  'apl-ud9/9.5.4': 'Per a cada missatge, pregunta\'t què et vol fer creure.<br>Per exemple, al primer: creus que realment la loteria recorda el resultat que ha sortit les setmanes anteriors?',
  'apl-ud9/9.5.5': 'És preferible començar amb una situació més senzilla. Tens un dau equilibrat i vols endevinar quin nombre sortirà, de l\'1 al 6.<br>Quantes vegades de mitjana creus que caldrà llançar el dau per tal que l\'encertis per primera vegada?',
  'apl-ud9/9.5.7': 'Recorda dues coses de l\'activitat:<br>- si cada jugada té un guany mitjà negatiu, què passa quan en fas moltes més?<br>- tu creus que la jugada d\'avui recorda el que vas perdre ahir?',
  'apl-ud9/9.5.9': 'Amb quota 1,80, si encertes et tornen 1,80 vegades els diners que hagis apostat. Per exemple, en una aposta de 10 €:<br>- si encertes, te\'n tornen 18 €, i per tant guanyes 8 €;<br>- si falles, perds els 10 €.',
  'apl-ud9/9.5.10': '<b>a)</b> Fes els càlculs amb la calculadora, amb tres decimals. Per exemple, la divisió 1 : 2,10 ≈ 0,476.<br><br><b>b)</b> Si la casa fos justa, la suma hauria de donar exactament 1.<br><br><b>c)</b> Calcula 1 dividit per la suma i expressa-ho en cèntims per euro.',
  'apl-ud9/9.5.11': 'Un any té 52 setmanes.<br>- En primer lloc, calcula el guany mitjà d\'una aposta.<br>- Posteriorment, el de totes les apostes de l\'any.<br>En una combinada de tres, només guanyes si encertes les tres apostes alhora: quina probabilitat hi ha d\'encertar-les totes?',
  'apl-ud9/U9.34': 'Compta quantes de les 40 cartes són asos o figures: les altres són les que et demanen.',
  'apl-ud9/U9.84': 'La suma de les probabilitats de totes les cares d\'un dau ha de ser 1. Per tant, tens aquesta equació:<br>3 · 1/7 + 3<i>x</i> = 1',
  'apl-ud9/U9.98': '<b>a)</b> «Ser un noi» i «ser una noia» són successos contraris: les dues probabilitats sumen 1.<br><br><b>b)</b> Anomenem <i>n</i> el nombre de membres: hi ha proporció directa entre les noies i el total.',
  'apl-ud9/U9.96': 'Fes una llista <b>ordenada</b> de totes les maneres d\'obtenir 36 multiplicant tres nombres de l\'1 al 6:<br>- 1 · 6 · 6<br>- 2 · 3 · 6<br>- …<br>Després, compta en quants ordres pot sortir cadascuna.<br><br><b>Atenció</b>: recorda que en total hi ha 6 · 6 · 6 = 216 casos possibles.',
  'apl-ud9/U9.102': 'Fes un diagrama d\'arbre: el primer jugador llança; si falla, llança el segon jugador; si aquest falla, llavors torna a llançar el primer jugador, etc.<br>La probabilitat que guanyi el primer és la suma de molts camins. Els primers termes són 1/2, 1/8, 1/32… Quin patró hi veus?'
};

function pistaDe(u, n){
  const t = PISTES[u + '/' + n];
  return t ? t : null;
}
